; eZ80 ADL mode assembly — generated by MinZ compiler
; Target: Agon Light 2 (eZ80 @ 18.432 MHz)

    .ASSUME ADL=1
    ORG $040045

; MOS entry preserves IY (firmware frame) and returns status in HL.
__agon_entry:
    PUSH IY
    CALL main
    POP IY
    LD HL, 0
    RET

; ── compilation summary ──────────────────────────────────────
; functions: 4  PBQP=4
; optimization passes fired: 4
; label audit: OK
; ─────────────────────────────────────────────────────────────
; generated by MIR2 Z80 codegen

; fun main() ; clobbers: A, B, BC, C, D, DE, E, F, H, HL, IX, IXH, IXL, IY, IYH, IYL, L
; [trace] backend=PBQP passes=[dse=1]
main:
    LD HL, _mir2_str_0
    ; genCall: mos_puts dst=0
    CALL mos_puts
    LD HL, _mir2_str_1
    ; genCall: mos_puts dst=0
    CALL mos_puts
    ; genCall: mos_getkey dst=8
    CALL mos_getkey
    LD HL, _mir2_str_2
    ; genCall: mos_puts dst=0
    JP mos_puts

; fun mos_putchar(ch: u8 = A) ; clobbers: A, B, BC, C, D, DE, E, F, H, HL, IX, IXH, IXL, IY, IYH, IYL, L
; [trace] backend=PBQP passes=[dse=1]
mos_putchar:
    RST.LIL $10
    RET

; fun mos_puts(str: ptr = HL) ; clobbers: A, B, BC, C, D, DE, E, F, H, HL, IX, IXH, IXL, IY, IYH, IYL, L
; [trace] backend=PBQP passes=[dse=1]
mos_puts:
    .loop: LD A, (HL)
    OR A
    RET Z
        RST.LIL $10
        INC HL
        JR .loop
    RET

; fun mos_getkey() -> u8 = A ; clobbers: A, B, BC, C, D, DE, E, F, H, HL, IX, IXH, IXL, IY, IYH, IYL, L
; [trace] backend=PBQP passes=[dse=1]
mos_getkey:
    LD A, $00
        RST.LIL $08
    RET

; strings
_mir2_str_0:
    DB "Hello from MinZ on Agon Light 2!", 13, 10, 0
_mir2_str_1:
    DB "Press any key: ", 0
_mir2_str_2:
    DB 13, 10, "You pressed a key!", 13, 10, 0
